			) : null}
			{document ? <DurableSharedUiDocument key={`${document.id}:${document.revision}`} document={document} metadata={metadata} storage={storage} hostAction={hostAction} /> : program ? (
				<div className={isStreaming ? css({ pointerEvents: "none", opacity: 0.78 }) : undefined}>
					<Renderer
						response={program}
						library={keatingOpenUILibrary}
						isStreaming={isStreaming}
						initialState={initialState}
						onAction={handleAction}
