function canonicalActionParams(action: UiAction): Record<string, unknown> {
	const {
		schemaVersion: _schemaVersion,
		documentId: _documentId,
		documentRevision: _documentRevision,
		idempotencyKey: _idempotencyKey,
		...params
	} = action;
	return params;
}

function DurableSharedUiDocument({
	document,
	metadata,
	storage,
	hostAction,
}: {
	document: UiDocument;
	metadata: OpenUIDocumentMetadata;
	storage: StorageLike | null;
	hostAction: KeatingOpenUIActionHandler | null;
}) {
	const transientStorage = useMemo(memoryStorage, []);
	const actionStorage = metadata.lifecycle === "ephemeral" ? transientStorage : storage;
	const [state, setState] = useState(() => loadSharedUiActionState(
		metadata.lifecycle === "ephemeral" ? null : storage,
		document,
	));
	const [actionError, setActionError] = useState<string | null>(null);

	const handleSharedAction = useCallback((event: { intent: SharedUiActionIntent; humanFriendlyMessage: string }) => {
		if (!actionStorage) {
			setActionError("This interaction could not be saved in this browser. Your entered work is still here; retry after enabling site storage.");
			return false;
		}
		try {
			const dispatched = dispatchSharedUiAction(actionStorage, state.document, event.intent);
			setState({ version: 1, document: dispatched.document, journal: dispatched.journal });
			setActionError(null);
			if (!dispatched.replayed) {
				hostAction?.({
					kind: "canonical",
					type: dispatched.action.type,
					humanFriendlyMessage: event.humanFriendlyMessage,
					params: canonicalActionParams(dispatched.action),
					document: {
						...metadata,
						id: dispatched.sourceDocument.id,
						revision: dispatched.sourceDocument.revision,
					},
					action: dispatched.action,
					sourceDocument: dispatched.sourceDocument,
					receipt: dispatched.receipt,
				});
			}
			return true;
		} catch (cause) {
			setActionError(cause instanceof Error
				? `This interaction was not saved: ${cause.message} Your entered work is still here; retry when ready.`
				: "This interaction was not saved. Your entered work is still here; retry when ready.");
			return false;
		}
	}, [actionStorage, hostAction, metadata, state.document]);

	return <>
		<SharedUiDocumentRenderer
			document={state.document}
			receipts={state.journal.receipts}
			onAction={handleSharedAction}
		/>
		{actionError ? <div className={css({ marginBlock: "0.75rem", borderRadius: "0.5rem", background: "color-mix(in srgb, var(--destructive) 10%, transparent)", padding: "0.75rem", fontSize: "0.75rem", color: "var(--destructive)" })} role="alert">{actionError}</div> : …1442 tokens truncated…on),
		updatedAt: now,
	};
	if (!validateUiDocument(document)) throw new Error("The OpenUI action produced an invalid document.");
	return document;
}

/**
 * Web's durable exactly-once boundary. The resulting document and completed
 * receipt are serialized into one localStorage value and committed with one
 * setItem call before any success UI or host learner turn is emitted.
 */
export function dispatchSharedUiAction(
	storage: Pick<StorageLike, "getItem" | "setItem">,
	sourceDocument: UiDocument,
	intent: SharedUiActionIntent,
	now = new Date().toISOString(),
): SharedUiActionDispatch {
	const action = createSharedUiAction(sourceDocument, intent);
	const state = loadSharedUiActionState(storage, sourceDocument);
	const currentDocument = state.document;
	const existing = receiptForUiAction(state.journal, action);
	if (existing) {
		if (!existing.result || existing.state !== "completed" || !existing.result.resultingDocument) {
			throw new Error("This OpenUI action has an incomplete durable receipt.");
		}
		return {
			action,
			sourceDocument: currentDocument,
			result: structuredClone(existing.result),
			receipt: structuredClone(existing),
			document: structuredClone(existing.result.resultingDocument),
			journal: structuredClone(state.journal),
			replayed: true,
		};
	}
	if (!validateUiActionAgainstDocument(action, currentDocument)) {
		throw new Error("This OpenUI action no longer applies to the current document revision.");
	}

	const resultingDocument = completedDocument(currentDocument, action, now);
	const result: UiActionResult = {
		schemaVersion: UI_CONTRACT_VERSION,
		documentId: action.documentId,
		sourceRevision: action.documentRevision,
		actionIdempotencyKey: action.idempotencyKey,
		status: "completed",
		documentLifecycle: resultingDocument.lifecycle,
		resultingDocument,
	};
	if (!validateUiActionResult(result)) throw new Error("The OpenUI completion result is invalid.");
	const receipt: UiActionReceipt = {
		schemaVersion: UI_CONTRACT_VERSION,
		action,
		actionFingerprint: canonicalUiAction(action),
		state: "completed",
		createdAt: now,
		updatedAt: now,
		result,
	};
	const journal: UiActionJournal = {
		...state.journal,
		receipts: [...state.journal.receipts, receipt],
	};
	if (!validateUiActionJournal(journal)) throw new Error("The OpenUI action journal is invalid or full.");
	const next: StoredSharedUiActionState = {
		version: 1,
		document: resultingDocument,
		journal,
	};
	storage.setItem(sharedUiActionStateKey(sourceDocument.id), JSON.stringify(next));
	return {
		action: structuredClone(action),
		sourceDocument: structuredClone(currentDocument),
		result: structuredClone(result),
		receipt: structuredClone(receipt),
		document: structuredClone(resultingDocument),
		journal: structuredClone(journal),
		replayed: false,
	};
}
