183 │ /**
184 │  * Web's durable exactly-once boundary. The resulting document and completed
185 │  * receipt are serialized into one localStorage value and committed with one
186 │  * setItem call before any success UI or host learner turn is emitted.
187 │  */
188 │ export function dispatchSharedUiAction(
189 │ 	storage: Pick<StorageLike, "getItem" | "setItem">,
190 │ 	sourceDocument: UiDocument,
191 │ 	intent: SharedUiActionIntent,
192 │ 	now = new Date().toISOString(),
193 │ ): SharedUiActionDispatch {
194 │ 	const action = createSharedUiAction(sourceDocument, intent);
195 │ 	const state = loadSharedUiActionState(storage, sourceDocument);
196 │ 	const currentDocument = state.document;
197 │ 	const existing = receiptForUiAction(state.journal, action);
198 │ 	if (existing) {
199 │ 		if (!existing.result || existing.state !== "completed" || !existing.result.resultingDocument) {
200 │ 			throw new Error("This OpenUI action has an incomplete durable receipt.");
201 │ 		}
202 │ 		return {
203 │ 			action,
204 │ 			sourceDocument: currentDocument,
205 │ 			result: structuredClone(existing.result),
206 │ 			receipt: structuredClone(existing),
207 │ 			document: structuredClone(existing.result.resultingDocument),
208 │ 			journal: structuredClone(state.journal),
209 │ 			replayed: true,
210 │ 		};
211 │ 	}
212 │ 	if (!validateUiActionAgainstDocument(action, currentDocument)) {
213 │ 		throw new Error("This OpenUI action no longer applies to the current document revision.");
214 │ 	}
215 │ 
216 │ 	const resultingDocument = completedDocument(currentDocument, action, now);
217 │ 	const result: UiActionResult = {
218 │ 		schemaVersion: UI_CONTRACT_VERSION,
219 │ 		documentId: action.documentId,
220 │ 		sourceRevision: action.documentRevision,
221 │ 		actionIdempotencyKey: action.idempotencyKey,
222 │ 		status: "completed",
223 │ 		documentLifecycle: resultingDocument.lifecycle,
224 │ 		resultingDocument,
225 │ 	};
226 │ 	if (!validateUiActionResult(result)) throw new Error("The OpenUI completion result is invalid.");
227 │ 	const receipt: UiActionReceipt = {
228 │ 		schemaVersion: UI_CONTRACT_VERSION,
229 │ 		action,
230 │ 		actionFingerprint: canonicalUiAction(action),
231 │ 		state: "completed",
232 │ 		createdAt: now,
233 │ 		updatedAt: now,
234 │ 		result,
235 │ 	};
236 │ 	const journal: UiActionJournal = {
237 │ 		...state.journal,
238 │ 		receipts: [...state.journal.receipts, receipt],
239 │ 	};
240 │ 	if (!validateUiActionJournal(journal)) throw new Error("The OpenUI action journal is invalid or full.");
241 │ 	const next: StoredSharedUiActionState = {
242 │ 		version: 1,
243 │ 		document: resultingDocument,
244 │ 		journal,
245 │ 	};
246 │ 	storage.setItem(sharedUiActionStateKey(sourceDocument.id), JSON.stringify(next));
247 │ 	return {
248 │ 		action: structuredClone(action),
249 │ 		sourceDocument: structuredClone(currentDocument),
250 │ 		result: structuredClone(result),
251 │ 		receipt: structuredClone(receipt),
252 │ 		document: structuredClone(resultingDocument),
253 │ 		journal: structuredClone(journal),
254 │ 		replayed: false,
255 │ 	};
256 │ }
