 13 │ function shortHash(value: string): string {
 14 │   let hash = 2166136261;
 15 │   for (let index = 0; index < value.length; index += 1) {
 16 │     hash ^= value.charCodeAt(index);
 17 │     hash = Math.imul(hash, 16777619);
 18 │   }
 19 │   return (hash >>> 0).toString(36);
 20 │ }
