 26 │ function actionTarget(document: UiDocument, nodeId: string): { node: UiDocumentNode; questionPrompt?: string } {
 27 │   for (const node of document.nodes) {
 28 │     if (node.id === nodeId) return { node, questionPrompt: node.type === "question" ? node.prompt : undefined };
 29 │     if (node.type === "quiz") {
 30 │       const question = node.questions.find((candidate) => candidate.id === nodeId);
 31 │       if (question) return { node, questionPrompt: question.prompt };
 32 │     }
 33 │   }
 34 │   throw new Error(`OpenUI action target ${nodeId} is missing.`);
 35 │ }
