 39 │   now: string,
 40 │   update: (nodes: UiDocumentNode[]) => UiDocumentNode[] = (nodes) => nodes,
 41 │   lifecycle: UiDocument["lifecycle"] = "ready",
 42 │ ): UiDocument {
 43 │   return {
 44 │     ...source,
 45 │     revision: source.revision + 1,
 46 │     lifecycle,
 47 │     nodes: update(structuredClone(source.nodes)),
 48 │     updatedAt: now,
