 52 │ function answerText(action: Extract<UiAction, { type: "submit-answer" | "choose-option" }>, document: UiDocument): string {
 53 │   if (action.type === "submit-answer") return serializeAnswer(action.answer);
 54 │   const target = actionTarget(document, action.nodeId);
 55 │   const question = target.node.type === "question"
 56 │     ? target.node
 57 │     : target.node.type === "quiz"
 58 │       ? target.node.questions.find((candidate) => candidate.id === action.nodeId)
 59 │       : undefined;
 60 │   const labels = new Map(question?.choices?.map((choice) => [choice.id, choice.label]) ?? []);
 61 │   return action.optionIds.map((id) => labels.get(id) ?? id).join(", ");
 62 │ }
