 64 │ function serializeAnswer(answer: UiAnswer): string {
 65 │   if (typeof answer === "string") return answer;
 66 │   if (answer.every((entry) => typeof entry === "string")) return answer.join(", ");
 67 │   return JSON.stringify(answer);
