 43 │ /** Stable structural comparison so JSON key insertion order cannot turn a retry into a conflict. */
 44 │ function stableJson(value: unknown): string {
 45 │   if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;
 46 │   if (!value || typeof value !== "object") return JSON.stringify(value);
 47 │   return `{${Object.entries(value as Record<string, unknown>)
 48 │     .sort(([left], [right]) => left.localeCompare(right))
 49 │     .map(([key, entry]) => `${JSON.stringify(key)}:${stableJson(entry)}`)
 50 │     .join(",")}}`;
 51 │ }
