243 │ /**
244 │  * Atomically appends a card's question-check batch. Any malformed or
245 │  * conflicting item aborts the entire batch before a snapshot is returned.
246 │  */
247 │ export function appendQuestionChecks(
248 │   data: PortableLearnerData,
249 │   checks: readonly LearnerQuestionCheck[],
250 │   nowIso: string,
251 │ ): PortableLearnerData {
252 │   requireValidSource(data);
253 │   requireMutationTimestamp(nowIso);
254 │   const known = new Map(data.questionChecks.map((check) => [check.id, check]));
255 │   const additions: LearnerQuestionCheck[] = [];
256 │   const incoming = new Map<string, LearnerQuestionCheck>();
257 │   for (const check of checks) {
258 │     if (!validateLearnerQuestionCheck(check)) throw new Error("Cannot append an invalid question check.");
259 │     const priorIncoming = incoming.get(check.id);
260 │     if (priorIncoming && !sameQuestionCheckEvidence(priorIncoming, check)) {
261 │       throw new Error(`Question check identity conflict for ${check.id}.`);
262 │     }
263 │     if (priorIncoming) continue;
264 │     incoming.set(check.id, check);
265 │     const existing = known.get(check.id);
266 │     if (existing) {
267 │       if (!sameQuestionCheckEvidence(existing, check)) throw new Error(`Question check identity conflict for ${check.id}.`);
268 │       continue;
269 │     }
270 │     additions.push(check);
271 │   }
272 │   if (additions.length === 0) return data;
273 │   return requireValidResult({
274 │     ...data,
275 │     generatedAt: nowIso,
276 │     questionChecks: [...data.questionChecks, ...additions.map((check) => structuredClone(check))],
277 │   });
278 │ }
