 29 │ /*
 30 │  * Two independent FNV-1a passes provide a compact, opaque 64-bit-ish identity
 31 │  * without adding a crypto dependency to the React Native runtime.  The input
 32 │  * is never placed in the id, which prevents a model-provided id from leaking
 33 │  * into exports or logs.  Structural index/type make IDs easy to reason about
 34 │  * and the digest distinguishes otherwise similar cards across retries.
 35 │  */
 36 │ function fnv1a32(value: string, seed: number): string {
 37 │   let hash = seed >>> 0;
 38 │   for (let index = 0; index < value.length; index += 1) {
 39 │     hash ^= value.charCodeAt(index);
 40 │     hash = Math.imul(hash, 0x01000193) >>> 0;
 41 │   }
 42 │   return hash.toString(16).padStart(8, "0");
 43 │ }
 44 │ 
 45 │ /**
 46 │  * A stable contract id for an interactive-card record.  `sourceKey` should be
 47 │  * the message/card key (for example `cardKey(message.id, cardIndex)`).
 48 │  */
 49 │ export function interactiveRecordId(kind: string, sourceKey: string, index: number): string {
 50 │   if (!/^[a-z][a-z0-9-]{0,31}$/.test(kind)) throw new Error("Interactive record kind is invalid.");
 51 │   if (!Number.isSafeInteger(index) || index < 0) throw new Error("Interactive record index must be a non-negative integer.");
 52 │   const identity = `${kind}\u0000${sourceKey}\u0000${index}`;
 53 │   const first = fnv1a32(identity, 0x811c9dc5);
 54 │   const second = fnv1a32(`${identity.length}\u0000${identity.split("").reverse().join("")}`, 0x9e3779b9);
 55 │   // Prefixes and hex are contract-id safe; sourceKey never appears verbatim.
 56 │   return `interactive-${kind}-${index}-${first}${second}`;
 57 │ }
