113 │   const canonicalIds = quiz.questions.map((_, index) => interactiveRecordId("quiz-question", sourceKey, index));
114 │   const record: LearnerQuizResult = {
115 │     id: interactiveRecordId("quiz", sourceKey, 0),
116 │     topic: quiz.topic,
117 │     createdAt: nowIso,
118 │     score: score.weighted,
119 │     totalQuestions: quiz.questions.length,
120 │     answers: Object.fromEntries(quiz.questions.map((question, index) => [canonicalIds[index], answers[question.id] ?? ""])),
121 │     partialCredits: Object.fromEntries(quiz.questions.map((question, index) => [canonicalIds[index], questionCredit(question, answers[question.id] ?? "")])),
122 │     pendingGradeQuestionIds: quiz.questions
123 │       .flatMap((question, index) => isOpenEnded(question) ? [canonicalIds[index]] : []),
