129 │ /**
130 │  * Stores every non-blank form answer as pending teacher evidence.  Answers,
131 │  * questions, and an authored topic are preserved byte-for-byte; omitted form
132 │  * topics use the explicit stable fallback "this lesson".
133 │  */
134 │ export function portableQuestionChecksFromInteractive(
135 │   form: QuestionForm,
136 │   answers: string[],
137 │   sourceKey: string,
138 │   nowIso: string,
139 │   sessionId?: string,
140 │ ): PortableQuestionChecksResult {
141 │   requireTimestamp(nowIso);
142 │   requireOptionalSession(sessionId);
143 │   const topic = form.topic ?? "this lesson";
144 │   const checks: LearnerQuestionCheck[] = [];
145 │   let skipped = 0;
146 │ 
147 │   form.questions.forEach((field, index) => {
148 │     const answer = answers[index] ?? "";
149 │     if (!answer.trim()) {
150 │       skipped += 1;
151 │       return;
152 │     }
153 │     checks.push(requireValid({
154 │       id: interactiveRecordId("question-check", sourceKey, index),
155 │       topic,
156 │       question: field.question,
157 │       answer,
158 │       createdAt: nowIso,
159 │       grading: "pending",
160 │       ...(sessionId === undefined ? {} : { sessionId }),
161 │     } satisfies LearnerQuestionCheck, validateLearnerQuestionCheck, "question check"));
162 │   });
163 │   return { checks, skipped };
164 │ }
