106 │ function readableValue(value: unknown): string | null {
107 │ 	if (typeof value === "string") return value.trim() || null;
108 │ 	if (typeof value === "number" || typeof value === "boolean") return String(value);
109 │ 	if (Array.isArray(value) && value.every((item) => ["string", "number", "boolean"].includes(typeof item))) {
110 │ 		return value.map(String).join(", ");
111 │ 	}
112 │ 	return null;
113 │ }
