115 │ function labelFromKey(key: string): string {
116 │ 	return key
117 │ 		.replace(/([a-z0-9])([A-Z])/g, "$1 $2")
118 │ 		.replace(/[_-]+/g, " ")
119 │ 		.replace(/^./, (character) => character.toUpperCase());
