148 │ 					? [{ label: "Score", value: total !== undefined ? `${score} of ${total}` : String(score) }]
149 │ 					: []),
150 │ 				...(flagged > 0 ? [{ label: "Marked for review", value: String(flagged) }] : []),
151 │ 			],
