209 │ export function parseLearnerResponse(text: string): LearnerResponseEnvelope | null {
210 │ 	const pattern = new RegExp(`^\\s*<${LEARNER_RESPONSE_TAG}(?:\\s+version=["']1["'])?>\\s*([\\s\\S]*)\\s*</${LEARNER_RESPONSE_TAG}>\\s*$`);
