212 │ 	if (!match) return null;
213 │ 	try {
214 │ 		const parsed = JSON.parse(match[1]) as Partial<LearnerResponseEnvelope>;
215 │ 		if (
216 │ 			parsed.version !== 1 ||
217 │ 			(parsed.kind !== "question" && parsed.kind !== "openui-action") ||
218 │ 			!parsed.review ||
219 │ 			typeof parsed.review.title !== "string" ||
220 │ 			!Array.isArray(parsed.review.items)
