176 │ export function computeGoalProgress(goal: LearnerGoal): GoalProgress {
177 │ 	const total = goal.steps.length;
178 │ 	const done = goal.steps.filter((s) => s.status === "done").length;
179 │ 	const inProgress = goal.steps.filter((s) => s.status === "in_progress").length;
180 │ 	const nextStep = goal.steps.find((s) => s.status !== "done");
181 │ 	return {
182 │ 		done,
183 │ 		inProgress,
184 │ 		total,
185 │ 		percent: total === 0 ? 0 : Math.round((done / total) * 100),
186 │ 		nextStep,
187 │ 	};
188 │ }
