190 │ /** Return a new goal with one step's status changed and goal status recomputed. */
191 │ export function advanceGoalStep(goal: LearnerGoal, stepId: string, status: GoalStepStatus): LearnerGoal {
192 │ 	const steps = goal.steps.map((step) =>
193 │ 		step.id === stepId
194 │ 			? {
195 │ 					...step,
196 │ 					status,
197 │ 					completedAt: status === "done" ? new Date().toISOString() : undefined,
198 │ 				}
199 │ 			: step,
200 │ 	);
201 │ 	const allDone = steps.length > 0 && steps.every((s) => s.status === "done");
202 │ 	return {
203 │ 		...goal,
204 │ 		steps,
205 │ 		status: allDone ? "completed" : goal.status === "completed" ? "active" : goal.status,
206 │ 		updatedAt: Date.now(),
207 │ 	};
208 │ }
