216 │ export function goalToMarkdown(goal: LearnerGoal): string {
217 │ 	const progress = computeGoalProgress(goal);
218 │ 	const lines = [
219 │ 		`# Goal: ${goal.title}`,
220 │ 		"",
221 │ 		goal.description || "_(no description)_",
222 │ 		"",
223 │ 		`**Progress:** ${progress.done}/${progress.total} steps (${progress.percent}%) · **Status:** ${goal.status}`,
224 │ 	];
225 │ 	if (goal.motivation) lines.push(`**Why:** ${goal.motivation}`);
226 │ 	if (goal.targetDate) lines.push(`**Target:** ${goal.targetDate}`);
227 │ 	if (progress.nextStep) lines.push(`**Next up:** ${progress.nextStep.title}`);
228 │ 	lines.push("", "## Curriculum", "");
229 │ 
230 │ 	for (const step of goal.steps) {
231 │ 		lines.push(`### ${STATUS_MARK[step.status]} ${step.order + 1}. ${step.title}  _(${step.kind})_`);
232 │ 		if (step.description) lines.push(step.description);
233 │ 		if (step.topic) lines.push(`*Topic:* ${step.topic}`);
234 │ 		if (step.successCriteria.length > 0) {
235 │ 			lines.push("*Success criteria:*");
236 │ 			for (const c of step.successCriteria) lines.push(`- ${c}`);
237 │ 		}
238 │ 		lines.push("");
239 │ 	}
240 │ 
241 │ 	return lines.join("\n") + "\n";
242 │ }
