  1 │ /**
  2 │  * SM-2 spaced repetition algorithm — Anki-compatible variant.
  3 │  *
  4 │  * Each card carries the SM-2 state vector: `ease`, `interval` (days), `reps`,
  5 │  * `lapses`. After every review the learner grades themselves 0..3:
  6 │  *   0 — Again  (failed recall; reset reps, schedule ~10 min later)
  7 │  *   1 — Hard   (recalled with serious difficulty; grow interval, ease -= 0.15)
  8 │  *   2 — Good   (recalled with some effort; grow interval, ease unchanged)
  9 │  *   3 — Easy   (recalled instantly; grow interval, ease += 0.15)
 10 │  *
 11 │  * The ease factor is clamped to [1.3, ∞) per SM-2. Intervals are clamped to
 12 │  * whole days with a 1-day minimum on success. The "Again" path uses a 10-minute
 13 │  * intra-day re-show window (`intervalDays < 1`).
 14 │  *
 15 │  * This is pure logic, easily testable, no LLM, no IO.
 16 │  */
 17 │ 
 18 │ import type { CardSrsState, Flashcard, FlashcardDeck, SrsRating } from "./flashcard-types";
 19 │ export type { CardSrsState, Flashcard, FlashcardDeck, SrsRating } from "./flashcard-types";
 20 │ 
 21 │ export const SRS_RATING_LABELS: Record<SrsRating, string> = {
 22 │ 	0: "Again",
 23 │ 	1: "Hard",
 24 │ 	2: "Good",
 25 │ 	3: "Easy",
 26 │ };
 27 │ 
 28 │ /** Initial SM-2 state for a freshly authored card. */
 29 │ export function initialSrsState(now: number = Date.now()): CardSrsState {
 30 │ 	return {
 31 │ 		ease: 2.5,
 32 │ 		intervalDays: 0,
 33 │ 		reps: 0,
 34 │ 		lapses: 0,
 35 │ 		dueAt: now, // due immediately on creation
 36 │ 		lastReviewedAt: 0,
 37 │ 		lastRating: null,
 38 │ 	};
 39 │ }
 40 │ 
 41 │ export const MS_PER_DAY = 86_400_000;
 42 │ /** Intra-day re-show window when the learner rates Again. */
 43 │ export const AGAIN_INTERVAL_MS = 10 * 60 * 1000;
 44 │ /** Minimum ease factor (SM-2 floors at 1.3). */
 45 │ export const MIN_EASE = 1.3;
 46 │ 
 47 │ export interface ReviewOutcome {
 48 │ 	/** The new SRS state. */
 49 │ 	next: CardSrsState;
 50 │ 	/** The interval, in days, applied after this review (for display). */
 51 │ 	appliedIntervalDays: number;
 52 │ 	/** True if the rating was a lapse (Again). */
 53 │ 	isLapse: boolean;
 54 │ }
 55 │ 
 56 │ export function applyReview(
 57 │ 	state: CardSrsState,
 58 │ 	rating: SrsRating,
 59 │ 	now: number = Date.now(),
 60 │ ): ReviewOutcome {
 61 │ 	const next: CardSrsState = { ...state };
 62 │ 
 63 │ 	if (rating === 0) {
 64 │ 		// Lapse: reset reps, schedule again in 10 minutes, ease drops.
 65 │ 		next.lapses = state.lapses + 1;
 66 │ 		next.reps = 0;
 67 │ 		next.intervalDays = 0;
 68 │ 		next.ease = Math.max(MIN_EASE, state.ease - 0.2);
 69 │ 		next.dueAt = now + AGAIN_INTERVAL_MS;
 70 │ 		next.lastReviewedAt = now;
 71 │ 		next.lastRating = rating;
 72 │ 		return { next, appliedIntervalDays: 0, isLapse: true };
 73 │ 	}
 74 │ 
 75 │ 	// Successful recall
 76 │ 	const prevEase = state.ease;
 77 │ 	let easeDelta = 0;
 78 │ 	if (rating === 1) easeDelta = -0.15;
 79 │ 	else if (rating === 2) easeDelta = 0;
 80 │ 	else if (rating === 3) easeDelta = 0.15;
 81 │ 	const newEase = Math.max(MIN_EASE, prevEase + easeDelta);
 82 │ 	next.ease = newEase;
 83 │ 	next.reps = state.reps + 1;
 84 │ 
 85 │ 	let interval: number;
 86 │ 	if (next.reps === 1) {
 87 │ 		interval = 1;
 88 │ 	} else if (next.reps === 2) {
 89 │ 		interval = 6;
 90 │ 	} else {
 91 │ 		// SM-2: I(n) = I(n-1) * EF
 92 │ 		interval = Math.max(1, Math.round(state.intervalDays * newEase));
 93 │ 	}
 94 │ 
 95 │ 	// Hard shortens the interval a touch compared to Good.
 96 │ 	if (rating === 1 && next.reps > 2) {
 97 │ 		interval = Math.max(1, Math.round(interval * 0.8));
 98 │ 	}
 99 │ 	// Easy stretches it a bit.
100 │ 	if (rating === 3 && next.reps > 2) {
101 │ 		interval = Math.max(1, Math.round(interval * 1.3));
102 │ 	}
103 │ 
104 │ 	next.intervalDays = interval;
105 │ 	next.dueAt = now + interval * MS_PER_DAY;
106 │ 	next.lastReviewedAt = now;
107 │ 	next.lastRating = rating;
108 │ 	return { next, appliedIntervalDays: interval, isLapse: false };
109 │ }
110 │ 
111 │ export function isDue(state: CardSrsState, now: number = Date.now()): boolean {
112 │ 	return state.dueAt <= now;
113 │ }
114 │ 
115 │ /** Format an interval in days as a human-readable string ("10m", "3d", "2w", "5mo"). */
116 │ export function formatInterval(intervalDays: number): string {
117 │ 	if (intervalDays < 1 / 24 / 6) return "10m";
118 │ 	if (intervalDays < 1) return `${Math.round(intervalDays * 24 * 60)}m`;
119 │ 	if (intervalDays < 30) return `${Math.round(intervalDays)}d`;
120 │ 	if (intervalDays < 365) return `${Math.round(intervalDays / 30)}mo`;
121 │ 	return `${(intervalDays / 365).toFixed(1)}y`;
122 │ }
123 │ 
124 │ /** Format a timestamp as a relative due label ("now", "in 3d", "5d overdue"). */
125 │ export function formatDueIn(dueAt: number, now: number = Date.now()): string {
126 │ 	const diffMs = dueAt - now;
127 │ 	const days = diffMs / MS_PER_DAY;
128 │ 	if (Math.abs(days) < 0.001) return "now";
129 │ 	if (diffMs < 0) {
130 │ 		const overdueDays = Math.abs(days);
131 │ 		if (overdueDays < 1) {
132 │ 			const overdueMin = Math.round(overdueDays * 24 * 60);
133 │ 			return overdueMin <= 60 ? `${overdueMin}m overdue` : `${Math.round(overdueDays)}d overdue`;
134 │ 		}
135 │ 		return `${Math.round(overdueDays)}d overdue`;
136 │ 	}
137 │ 	if (days < 1) {
138 │ 		const minutes = Math.round(days * 24 * 60);
139 │ 		return minutes <= 60 ? `in ${minutes}m` : "in <1d";
140 │ 	}
141 │ 	return `in ${Math.round(days)}d`;
142 │ }
