152 │ export function getDeckStats(deck: FlashcardDeck, now: number = Date.now()): {
153 │ 	total: number;
154 │ 	dueNow: number;
155 │ 	fresh: number;
156 │ 	learning: number;
157 │ 	review: number;
158 │ 	mature: number;
159 │ } {
160 │ 	let dueNow = 0;
161 │ 	let fresh = 0;
162 │ 	let learning = 0;
163 │ 	let review = 0;
164 │ 	let mature = 0;
165 │ 	for (const card of deck.cards) {
166 │ 		if (isDue(card.srs, now)) dueNow += 1;
167 │ 		if (card.srs.reps === 0) fresh += 1;
168 │ 		else if (card.srs.intervalDays < 21) learning += 1;
169 │ 		else if (card.srs.intervalDays < 90) review += 1;
170 │ 		else mature += 1;
171 │ 	}
172 │ 	return { total: deck.cards.length, dueNow, fresh, learning, review, mature };
173 │ }
