175 │ /** Order the given due cards using a simple scheduler: lapses first, then oldest-due. */
176 │ export function scheduleDueCards(cards: Flashcard[], now: number = Date.now()): Flashcard[] {
177 │ 	return [...cards].sort((a, b) => {
178 │ 		// Lapses float to the top of the queue.
179 │ 		if ((a.srs.lapses > 0) !== (b.srs.lapses > 0)) return a.srs.lapses > 0 ? -1 : 1;
180 │ 		return a.srs.dueAt - b.srs.dueAt;
181 │ 	});
182 │ }
