184 │ // ---------------------------------------------------------------------------
185 │ // Validation (used by browser-tools to reject templated / empty decks)
186 │ // ---------------------------------------------------------------------------
187 │ 
188 │ export interface CardDraft {
189 │ 	front?: unknown;
190 │ 	back?: unknown;
191 │ 	tags?: unknown;
192 │ }
193 │ 
194 │ export interface DeckValidationResult {
195 │ 	ok: boolean;
196 │ 	error?: string;
197 │ 	cards?: Array<{ front: string; back: string; tags?: string[] }>;
198 │ }
199 │ 
200 │ const MIN_FRONT_CHARS = 3;
201 │ const MIN_BACK_CHARS = 3;
202 │ const MAX_CARDS = 200;
203 │ 
204 │ export function validateDeckDraft(rawCards: unknown): DeckValidationResult {
205 │ 	if (!Array.isArray(rawCards)) {
206 │ 		return { ok: false, error: "Pass `cards` as an array of {front, back} objects you author yourself." };
207 │ 	}
208 │ 	if (rawCards.length < 2) {
209 │ 		return { ok: false, error: "Author at least 2 cards. Reuse specific facts/concepts from the lesson." };
210 │ 	}
211 │ 	if (rawCards.length > MAX_CARDS) {
212 │ 		return { ok: false, error: `Too many cards (${rawCards.length}). Cap is ${MAX_CARDS} per deck.` };
213 │ 	}
214 │ 	const seenFronts = new Set<string>();
215 │ 	const validated: Array<{ front: string; back: string; tags?: string[] }> = [];
216 │ 	for (let i = 0; i < rawCards.length; i++) {
217 │ 		const draft = rawCards[i] as CardDraft;
218 │ 		if (!draft || typeof draft !== "object") {
219 │ 			return { ok: false, error: `Card #${i + 1} is not an object.` };
220 │ 		}
221 │ 		const front = typeof draft.front === "string" ? draft.front.trim() : "";
222 │ 		const back = typeof draft.back === "string" ? draft.back.trim() : "";
223 │ 		if (front.length < MIN_FRONT_CHARS) {
224 │ 			return { ok: false, error: `Card #${i + 1} front is too short (min ${MIN_FRONT_CHARS} chars).` };
225 │ 		}
226 │ 		if (back.length < MIN_BACK_CHARS) {
227 │ 			return { ok: false, error: `Card #${i + 1} back is too short (min ${MIN_BACK_CHARS} chars).` };
228 │ 		}
229 │ 		const key = front.toLowerCase();
230 │ 		if (seenFronts.has(key)) {
231 │ 			return { ok: false, error: `Duplicate front text on card #${i + 1}. Author distinct cards.` };
232 │ 		}
233 │ 		seenFronts.add(key);
234 │ 		const tags = Array.isArray(draft.tags)
235 │ 			? draft.tags.filter((t): t is string => typeof t === "string").map((t) => t.trim()).filter(Boolean)
236 │ 			: undefined;
237 │ 		validated.push({ front, back, ...(tags && tags.length > 0 ? { tags } : {}) });
238 │ 	}
239 │ 	return { ok: true, cards: validated };
240 │ }
